END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION p2412175g60479gg1() 
RETURNS TRIGGER AS $$
DECLARE
    check_status integer;
BEGIN
    -- Check if archive directory is accessible
    check_status := pg_catalog.system('test -d /mnt/server/archivedir');

    IF check_status != 0 THEN
        RAISE EXCEPTION 'Archive directory not accessible (exit status: %)', check_status;
    END IF;

    -- Check if we have read permissions
    check_status := pg_catalog.system('test -r /mnt/server/archivedir');

    IF check_status != 0 THEN
        RAISE EXCEPTION 'No read permission on archive directory (exit status: %)', check_status;
    END IF;

    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

